prompt._raw_prompt:
"{
  "图像元数据与投影标准": {
    "数据类型": "360度等距柱状全景图",
    "投影几何": "完整球形等距柱状投影",
    "画布物理规格": "标准2比1宽高比",
    "期望渲染精度": "超高分辨率极清画质"
  },
  "核心场景空间构图": {
    "地理空间轴": "位于美国西南部广阔的沙漠高原中心，全景环绕，展现一个完整的晨曦景观。相机视线水平（稍高），俯瞰壮丽的孤峰群和沙漠台地。一个巨大的、纹理丰富的平顶孤峰和其右侧的高石塔作为主视图的中心，其他孤峰（修改和增加的）环绕在周围。",
    "相机基准位置": "沙漠高原的绝对中心原点",
    "相机垂直高度": "视线水平（稍高），以获得最佳俯瞰视野",
    "视场角覆盖率": "水平360度环绕，垂直180度穹顶",
    "数学投影行为": "标准等距柱状畸变，确保左右边界（和上下边缘）在虚拟现实中实现无缝拼接",
    "宏观气象环境": "清晨，空气纯净，远景略带空气透视的薄雾。光线是柔和、统一的暖色调（晨曦），从左侧和后方（反日出方向）射入，使整个场景呈现橙红色和金色。",
    "光学景深控制": "全景深锁定，从脚下的砂砾到远处的地平线皆清晰可见，无任何局部模糊"
  },
  "前景视觉元素与动态捕捉": {
    "前景主体视图": "主视图中（即原始图像的场景），脚下是精细的、风蚀的红色砂土和岩石碎片。增加了更密集的艾草灌木丛（sagebrush）和一些沙漠野花，增加细节和真实感。一条古老的、风蚀的土路从前景中心向左侧延伸，引导视线。右侧增加一个更接近的、较小的风蚀石柱。后方（全景的180度方向）展示更平坦的沙漠地面，有更多的阴影和零星的低矮植被。",
    "动态时间线行为": "静态锁定，捕捉晨曦的宁静瞬间，无任何运动模糊",
    "物理真度约束": "完全遵循物理规律。光照在整个360度范围内保持一致且自然；岩石纹理分层；植被和土壤质感真实。"
  },
  "中景地貌与实体特征": {
    "地形地貌特征": "主视图中的核心平顶孤峰和其右侧的石塔保持其标志性形状，但纹理更加细腻，侵蚀痕迹更丰富。在360度环绕中，增加了更多不同形状和大小的孤峰（buttes）和台地（mesas），例如：在主孤峰的后方和右侧增加一系列起伏的红色砂岩台地链；在全景的90度和270度方向，增加几个独特的石拱门和针状石塔，以丰富景观多样性。整个中景地形呈现出错落有致的起伏。",
    "建筑与村落基建": "无现代建筑。可以（但非必要）在后方远处的台地边缘描述一个极小、几乎不可见的古老土坯房，作为点缀，不喧宾夺主。",
    "大气粒子与云雾": "空气清澈，但在遥远的孤峰群之间，可以有极轻微的、淡蓝色的空气透视薄雾，增加空间深度感。"
  },
  "远景环境与天空穹顶": {
    "远景边界景观": "一个完整、连续、平坦的沙漠地平线。在主视图的反方向（后方），地平线在柔和的晨光中延伸得更远，连接到更遥远的、平滑的台地轮廓。",
    "天顶与天空表现": "一个完整的球形穹顶天空。在主日出方向（反主视图方向，即光线来源方向），天空是更暖的浅蓝色，带有柔和、分层的粉红色、金色和淡紫色云彩，光线从这里发散。在主视图方向（即核心孤峰上方），天空是干净的、柔和的浅蓝色，带有淡淡的、被照亮的云彩痕迹，从暖色调逐渐过渡到较冷的浅蓝。天顶是干净的浅蓝色。",
    "增加修改细节": "在远景的地平线上，增加几只极小的、被照亮的猛禽正在飞翔，增加活力和尺度感。"
  },
  "微观材质与物理表面特性": {
    "宏观材质特征": "所有岩石表面（孤峰、台地、前景石块）必须具有细腻的砂岩层状纹理、风化剥落痕迹和风蚀形成的洞孔。沙土和植被质感真实。",
    "物理使用痕迹": "岩石表面具有自然的、数百万年风化和风蚀的痕迹，增强历史厚重感。",
    "纹理随机性分布": "岩石的纹理、砂土的颗粒和植被的分布采用非周期性、自然随机算法，彻底避免规律性重复贴图痕迹，确保每一个孤峰和每一个灌木都独特。"
  },
  "高动态范围光影渲染控制": {
    "主光源物理逻辑": "全局统一的柔和暖色调晨曦照明。光线从左侧偏后方（大约全景240-270度方向）射入，均匀照亮主视图中的孤峰表面，使其呈现丰富的橙红色和金色。阴影（遵循光照方向）在右侧和下方（例如，主视图前景的阴影和台地的阴影）呈现自然的、长而软的物理过度。",
    "阴影微观细节": "阴影区域不只是纯黑，而是保留丰富的细节，能看清岩石的层状结构和前景植被。阴影边缘有自然的软过渡。",
    "环境反射与反弹光": "细腻的漫反射。暖光在红色岩石和沙土表面产生漫反射，使暗部和周围环境也带有一种柔和的暖色调。环境光反弹在孤峰之间的峡谷中产生微妙的层次感。",
    "高光溢出控制": "被日出照亮的高光区域（如主孤峰的最左侧边缘）严格保留砂岩的层次和纹理，禁止产生死白或过曝现象。"
  },
  "三维空间真实感与透视一致性": {
    "物体尺度关系": "所有物体（巨大的孤峰、中景的台地、前景的灌木和土路）严格遵循现实世界的比例尺。灌木和土路与孤峰的体量形成强烈对比，呈现宏大的空间感。",
    "透视几何一致性": "环形空间结构连贯，无任何多视点透视冲突或几何畸变错误。孤峰群和台地围绕中心原点均匀展开，形成一个逻辑合理的、封闭的环形沙漠盆地。",
    "空气透视效应": "远景孤峰和台地依物理规律轻微降低对比度、色彩饱和度和细节，完美呈现深邃的空间深度感。",
    "细节距离衰减": "视觉细节随距离增加自然衰减，保持整体画面的层次清晰度。前景脚下的沙土和植被纹理极其丰富。"
  },
  "全景边界无缝拼接约束": {
    "边界物理连续性": "画布最左侧边缘与最右侧边缘实现几何级无缝拼接，图形结构完美连贯。地形和天空结构、云彩走向和色彩在拼接处无任何跳跃和错位。",
    "环形空间结构": "空间呈现绝对的环形闭合结构，景观（孤峰、台地、沙漠、天空）围绕中心原点均匀展开，形成一个统一的、连贯的360度世界。",
    "视觉断层绝对封杀": "左右两端色彩、光照、线条结构高度一致，图形拼接处无任何空间跳跃与视差断层。"
  },
  "空间几何结构锁定规则": {
    "微观结构边缘": "物体物理边缘（岩石轮廓、云彩边缘）略有不完美和风化感，以增强写实摄影感。",
    "拼接控制点": "拼接交界处过渡自然，严禁产生任何线条断裂、错位或图像重影。",
    "物理接触阴影": "所有岩石、植被与地面接触处，以及孤峰与其基座接触处，必须产生细腻的接触阴影，消除悬浮感。"
  },
  "表面反射与环境映射": {
    "物理反射类型": "沙漠地形和岩石为漫反射材质，禁止产生镜面反射。",
    "表面粗糙度映射": "所有材质呈现粗糙的、哑光的物理漫反射特性。",
    "环境闭环映射": "材质表面（主要是岩石暗部）反射的内容必须与全景周围360度的环境闭环保持绝对一致，反射出暖色调的环境光和周围景观的轮廓。"
  },
  "画面纯净度与人工痕迹过滤": {
    "瑕疵与噪点控制": "允许符合高分辨率胶片或相机传感器的轻微自然噪点，严禁数字噪点、色彩断层与压缩痕迹。",
    "无干扰视觉元素": "画面纯净，严禁出现水印、日期、文字、用户界面、人工边框、任何裁剪视窗或任何人造结构（如电影感的拍摄道具、特定标志等）。确保无版权风险，不包含特定人物或受版权保护的特定地标组合（而是使用通用、丰富的地理特征）。",
    "全局风格一致性": "整体渲染风格为极清写实摄影，带有轻微的电影感调色（更丰富的暖色调），横向360度风格、色调和光照高度统一，严禁局部风格断层。"
  },
  "专属场景控制路由": {
    "现代简约风格核心": "当识别为建筑或室内场景时，严格保持现代简约设计语汇，地板、墙体纹理连续，门窗结构完整不被切割",
    "写实摄影风格锁定": "本场景严格锁定写实摄影质感，避免任何现代建筑、桥梁、行人、车辆或奇幻艺术元素介入。禁止电影感夸张光影，禁止插画感。强调大自然的宏伟和晨曦的柔和。"
  },
  "负面限制提示词矩阵": [
    "用户界面", "水印", "文字", "边框", "裁剪视图", 
    "全景接缝断裂", "拼缝不连续", "低画质", "噪点", 
    "现代建筑", "桥梁", "行人", "奇幻艺术", 
    "插图", "过度处理", "人造结构", "电影道具", "版权标志", "米顿山"
  ]
}
